import type { Customer, LineItem, Order } from "./types.js";

export const TAX_RATE = 0.08;
const GOLD_DISCOUNT = 0.1;

export function lineTotalCents(item: LineItem): number {
  return item.quantity * item.unitPriceCents;
}

export function subtotalCents(order: Order): number {
  return order.items.reduce((sum, item) => sum + lineTotalCents(item), 0);
}

/** Line total in major units (e.g. dollars). */
export function lineTotal(item: LineItem): number {
  return lineTotalCents(item) / 100;
}

/** Subtotal in major units (e.g. dollars). */
export function subtotal(order: Order): number {
  return subtotalCents(order) / 100;
}

export function discount(order: Order, customer: Customer): number {
  return customer.tier === "gold" ? (subtotalCents(order) * GOLD_DISCOUNT) / 100 : 0;
}

export function orderTotal(order: Order, customer: Customer): number {
  const netCents = subtotalCents(order) - discount(order, customer) * 100;
  return Math.round(netCents * (1 + TAX_RATE)) / 100;
}
