import type { Currency, Customer, Order } from "./types.js";
import { orderTotal } from "./pricing.js";
import { statusLabel } from "./status.js";

const SYMBOLS: Record<Currency, string> = { USD: "$", EUR: "€", BRL: "R$" };

export function formatMoney(amount: number, currency: Currency = "USD"): string {
  return `${SYMBOLS[currency]}${amount.toFixed(2)}`;
}

export function formatCents(cents: number, currency: Currency = "USD"): string {
  return formatMoney(cents / 100, currency);
}

export function fullName(customer: Customer): string {
  return `${customer.firstName} ${customer.lastName}`;
}

export function formatOrder(order: Order, customer: Customer): string {
  const lines = order.items.map(
    (item) => `  ${item.quantity} x ${item.sku} @ ${formatCents(item.unitPriceCents, order.currency)}`,
  );
  return [
    `Order ${order.id} for ${fullName(customer)} (${statusLabel(order.status)})`,
    ...lines,
    `  Total: ${formatMoney(orderTotal(order, customer), order.currency)}`,
  ].join("\n");
}
